files.content:
* {
  box-sizing: border-box;
}

body {
  min-width: 850px;
  margin: 0;
  padding: 25px;
  font-family: 'Open Sans', sans-serif;
  font-size: 18px;
  background-image: url(https://code.s3.yandex.net/web-code/images/dotted.svg);
}

.section {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 25px;
  box-sizing: border-box;
  height: 100vh;
  min-height: 550px;
  border: 1px solid #000;
  padding: 25px;
  background-color: #fff;
}

.section:not(:last-child) {
  margin-bottom: 50px;
}

.section-content {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  width: 50%;
  height: 100%;
}

.section-block {
  flex-grow: 1;
  width: 40%;
  height: 50%;
  border: 1px solid #000;
}

.section-image {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center;
}

.section-title {
  margin: 0;
  font-weight: 800;
  font-size: 38px;
  text-transform: uppercase;
  position: sticky;
}
